#include <stdio.h>
#include <string.h>

int is_palindrome(const char *s) {
    for (int i = 0, j = strlen(s) - 1; i < j; i++, j--) {
        if (s[i] != s[j]) {
            return 0;
        }
    }
    return 1;
}

int main() {
    printf("%s\n", is_palindrome("madam") ? "palindrome" : "not palindrome");
    return 0;
}
